#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> luckyNumbers(std::vector<std::vector<int>>& matrix) {
        int R = matrix.size(), C = matrix[0].size();
        std::vector<int> rowMins(R), colMaxs(C, 0);
        for (int r = 0; r < R; ++r) {
            int curMin = matrix[r][0];
            for (int c = 1; c < C; ++c) curMin = std::min(curMin, matrix[r][c]);
            rowMins[r] = curMin;
        }
        for (int c = 0; c < C; ++c) {
            int curMax = matrix[0][c];
            for (int r = 1; r < R; ++r) curMax = std::max(curMax, matrix[r][c]);
            colMaxs[c] = curMax;
        }
        std::vector<int> res;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (matrix[r][c] == rowMins[r] && matrix[r][c] == colMaxs[c]) {
                    res.push_back(matrix[r][c]);
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> luckyNumbers (int[][] matrix) {
        int R = matrix.length, C = matrix[0].length;
        int[] rowMins = new int[R];
        int[] colMaxs = new int[C];
        for (int r = 0; r < R; r++) {
            int mn = matrix[r][0];
            for (int c = 1; c < C; c++) mn = Math.min(mn, matrix[r][c]);
            rowMins[r] = mn;
        }
        for (int c = 0; c < C; c++) {
            int mx = matrix[0][c];
            for (int r = 1; r < R; r++) mx = Math.max(mx, matrix[r][c]);
            colMaxs[c] = mx;
        }
        List<Integer> res = new ArrayList<>();
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (matrix[r][c] == rowMins[r] && matrix[r][c] == colMaxs[c]) {
                    res.add(matrix[r][c]);
                }
            }
        }
        return res;
    }
}

var luckyNumbers  = function(matrix) {
    const R = matrix.length, C = matrix[0].length;
    const rowMins = matrix.map(row => Math.min(...row));
    const colMaxs = [];
    for (let c = 0; c < C; c++) {
        let mx = matrix[0][c];
        for (let r = 1; r < R; r++) mx = Math.max(mx, matrix[r][c]);
        colMaxs.push(mx);
    }
    const res = [];
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (matrix[r][c] === rowMins[r] && matrix[r][c] === colMaxs[c]) {
                res.push(matrix[r][c]);
            }
        }
    }
    return res;
};
